-- ===== 0031_trackers.sql =====
-- Phase 4b: trackers and their entries (spec 9.1; plan decisions 1 to 4). Private to the person:
-- nothing here touches XP, progress, the feed or challenges, and no function is redefined.

-- Trackers --------------------------------------------------------------------------------------
-- The id comes from the device (the offline queue stays idempotent). No delete: archiving is an
-- update, and the history stays.

create table public.trackers (
  id          uuid primary key,
  user_id     uuid not null references auth.users on delete cascade default auth.uid(),
  name        text not null check (char_length(btrim(name)) between 1 and 40 and name = btrim(name)),
  icon        text not null check (icon ~ '^[a-z][a-z0-9-]{0,31}$'),
  kind        text not null check (kind in ('number', 'duration', 'label')),
  unit        text check (unit is null or char_length(unit) <= 12),
  decimals    smallint check (decimals is null or decimals between 0 and 2),
  aggregate   text check (aggregate is null or aggregate in ('sum', 'avg')),
  options     jsonb,
  sort        integer not null default 0,
  archived_at timestamptz,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  check ((kind = 'label') = (options is not null and aggregate is null)),
  check (kind = 'label' or aggregate is not null),
  check (kind = 'number' or (unit is null and decimals is null))
);

alter table public.trackers enable row level security;
revoke all on public.trackers from anon;
revoke delete, truncate on public.trackers from authenticated;

create policy trackers_select_own on public.trackers
  for select to authenticated using (user_id = auth.uid());
create policy trackers_insert_own on public.trackers
  for insert to authenticated with check (user_id = auth.uid());
create policy trackers_update_own on public.trackers
  for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());

-- Entries ---------------------------------------------------------------------------------------
-- One value per entry, the one the tracker's kind asks for: value (number), minutes (duration) or
-- option (label, the id of one of the tracker's options, so renaming an option renames its entries).

create table public.tracker_entries (
  id         uuid primary key,
  tracker_id uuid not null references public.trackers on delete cascade,
  user_id    uuid not null references auth.users on delete cascade default auth.uid(),
  day        date not null,
  at         time not null check (extract(second from at) = 0),
  value      numeric(12, 2),
  minutes    smallint check (minutes between 1 and 1440),
  option     text,
  note       text check (char_length(note) <= 140),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (num_nonnulls(value, minutes, option) = 1)
);
create index tracker_entries_tracker_day on public.tracker_entries (tracker_id, day);

alter table public.tracker_entries enable row level security;
revoke all on public.tracker_entries from anon;
revoke truncate on public.tracker_entries from authenticated;

create policy tracker_entries_select_own on public.tracker_entries
  for select to authenticated using (user_id = auth.uid());
create policy tracker_entries_insert_own on public.tracker_entries
  for insert to authenticated with check (user_id = auth.uid());
create policy tracker_entries_update_own on public.tracker_entries
  for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy tracker_entries_delete_own on public.tracker_entries
  for delete to authenticated using (user_id = auth.uid());

-- Guards ----------------------------------------------------------------------------------------

-- Security invoker: RLS keeps a client on its own trackers and entries, so the count and the
-- option lookup are the owner's.
create function public.trackers_guard() returns trigger
language plpgsql security invoker set search_path = public as $$
begin
  if tg_op = 'UPDATE' and (new.id <> old.id or new.user_id <> old.user_id or new.kind <> old.kind) then
    raise exception 'item_immutable' using errcode = 'P0001';
  end if;

  -- created_at never changes, and a client cannot date a tracker in the future (app_now() is now()
  -- outside the tests).
  if tg_op = 'UPDATE' then
    new.created_at := old.created_at;
  elsif current_user in ('authenticated', 'anon') then
    new.created_at := least(new.created_at, public.app_now());
  end if;

  -- Last write wins: the client's updated_at, capped at now(); an older write is dropped.
  new.updated_at := least(new.updated_at, now());
  if tg_op = 'UPDATE' and new.updated_at < old.updated_at then
    return null;
  end if;

  -- Options of a label tracker: 2 to 8 objects { id, text } in order, ids unique within the
  -- tracker. A missing list is left to the table checks, which let a list through on a number
  -- tracker: options belong to labels only.
  if new.kind <> 'label' and new.options is not null then
    raise exception 'invalid_options' using errcode = 'P0001';
  end if;
  if new.kind = 'label' and new.options is not null then
    if jsonb_typeof(new.options) <> 'array' then
      raise exception 'invalid_options' using errcode = 'P0001';
    end if;
    if jsonb_array_length(new.options) not between 2 and 8 then
      raise exception 'invalid_options' using errcode = 'P0001';
    end if;
    if exists (
         select 1 from jsonb_array_elements(new.options) o
          where case when jsonb_typeof(o) <> 'object' then true
                     else o - 'id' - 'text' <> '{}'::jsonb
                       or jsonb_typeof(o -> 'id') is distinct from 'string'
                       or jsonb_typeof(o -> 'text') is distinct from 'string'
                       or coalesce(o ->> 'id' !~ '^[a-z0-9]{1,16}$', true)
                       or coalesce(char_length(o ->> 'text') not between 1 and 24, true)
                       or coalesce(o ->> 'text' <> btrim(o ->> 'text'), true) end)
       or (select count(distinct o ->> 'id') from jsonb_array_elements(new.options) o)
          <> jsonb_array_length(new.options) then
      raise exception 'invalid_options' using errcode = 'P0001';
    end if;
  end if;

  -- Renaming, reordering and adding options are free; removing one that an entry uses is not.
  if tg_op = 'UPDATE' and old.kind = 'label' and exists (
       select 1 from jsonb_array_elements(old.options) o
        where not exists (select 1 from jsonb_array_elements(new.options) n where n ->> 'id' = o ->> 'id')
          and exists (select 1 from public.tracker_entries e
                       where e.tracker_id = old.id and e.option = o ->> 'id')) then
    raise exception 'option_in_use' using errcode = 'P0001';
  end if;

  -- A new active tracker or a reactivated one. The id is left out of the count, so re-sending a
  -- tracker that is already active (an upsert from the queue) is not a 31st.
  if new.archived_at is null and (tg_op = 'INSERT' or old.archived_at is not null) then
    perform pg_advisory_xact_lock(hashtextextended('trackers:' || new.user_id::text, 0));
    if (select count(*) from public.trackers
         where user_id = new.user_id and archived_at is null and id <> new.id) >= 30 then
      raise exception 'too_many_trackers' using errcode = 'P0001';
    end if;
  end if;
  return new;
end $$;

create trigger trackers_guard before insert or update on public.trackers
  for each row execute function public.trackers_guard();

-- Security invoker: a client only sees its own trackers, so another person's reads as missing. The
-- day rules apply to client roles only (my_local_today() is the signed-in person's today, which RLS
-- makes the row owner's); the database owner passes them, as in the other guards.
create function public.tracker_entries_guard() returns trigger
language plpgsql security invoker set search_path = public as $$
declare
  v_tracker public.trackers;
begin
  if tg_op = 'UPDATE'
     and (new.id <> old.id or new.tracker_id <> old.tracker_id or new.user_id <> old.user_id) then
    raise exception 'item_immutable' using errcode = 'P0001';
  end if;

  -- For share: the tracker cannot be archived or lose an option on another connection until this
  -- write commits.
  select * into v_tracker from public.trackers where id = new.tracker_id and user_id = new.user_id for share;
  if not found then
    raise exception 'tracker_not_found' using errcode = 'P0001';
  end if;

  if current_user in ('authenticated', 'anon') then
    if new.day > public.my_local_today() then
      raise exception 'future_day' using errcode = 'P0001';
    end if;
    -- An archived tracker takes no new entry. The queue edits with an upsert, whose insert half
    -- runs this too: an entry that already exists is an edit.
    if tg_op = 'INSERT' and v_tracker.archived_at is not null
       and not exists (select 1 from public.tracker_entries where id = new.id and tracker_id = new.tracker_id) then
      raise exception 'tracker_archived' using errcode = 'P0001';
    end if;
  end if;

  -- The value the kind asks for (a second one filled in is left to the table check). A number
  -- tracker without decimals keeps the column's 2. A stored value written before the tracker lost
  -- decimals stays as it is while an edit leaves it alone (the upsert's insert half included).
  if (case v_tracker.kind
        when 'number' then new.value is null
                           or (round(new.value, coalesce(v_tracker.decimals, 2)) <> new.value
                               and not exists (select 1 from public.tracker_entries e
                                                where e.id = new.id and e.tracker_id = new.tracker_id
                                                  and e.value = new.value))
        when 'duration' then new.minutes is null
        else new.option is null
             or not exists (select 1 from jsonb_array_elements(v_tracker.options) o
                             where o ->> 'id' = new.option) end) then
    raise exception 'invalid_value' using errcode = 'P0001';
  end if;

  if tg_op = 'UPDATE' then
    new.created_at := old.created_at;
  elsif current_user in ('authenticated', 'anon') then
    new.created_at := least(new.created_at, public.app_now());
  end if;

  -- Last write wins: the client's updated_at, capped at now(); an older write is dropped.
  new.updated_at := least(new.updated_at, now());
  if tg_op = 'UPDATE' and new.updated_at < old.updated_at then
    return null;
  end if;
  return new;
end $$;

create trigger tracker_entries_guard before insert or update on public.tracker_entries
  for each row execute function public.tracker_entries_guard();

revoke all on function public.trackers_guard(), public.tracker_entries_guard()
  from public, anon, authenticated;
